/** 방의 두루마리 한 판입니다. 다시 엮을 때마다 version이 1씩 올라간 새 두루마리가 생긴다. */
package com.dandimate.durooduroo.scroll.domain;
import jakarta.persistence.*; import java.time.LocalDateTime; import java.util.UUID;
@Entity @Table(name="scrolls") public class Scroll { @Id private String id; @Column(nullable=false) private String roomId; @Column(nullable=false) private int version; /** MySQL에서 @Lob String은 TINYTEXT(255바이트)가 되므로 길이를 지정해 MEDIUMTEXT로 만든다. */ @Column(nullable=false,length=1_000_000) private String body; @Column(nullable=false) private LocalDateTime createdAt; protected Scroll(){} private Scroll(String r,int v,String b){id=UUID.randomUUID().toString();roomId=r;version=v;body=b;createdAt=LocalDateTime.now();} public static Scroll create(String roomId,int version,String body){return new Scroll(roomId,version,body);} public String getId(){return id;} public String getRoomId(){return roomId;} public int getVersion(){return version;} public String getBody(){return body;} public LocalDateTime getCreatedAt(){return createdAt;} }
